sql:
SELECT ROUND(100.0 * SUM(CASE WHEN is_weekend THEN 1 ELSE 0 END) / COUNT(*), 1) AS pct_weekend
FROM crashes
WHERE drivers_18_to_25 > 0 AND is_complete_year = true;

